import os

def chown(dir='/tmp', user='test', group='bats'):
    entries = os.listdir(dir)
    for file in entries:
        path = os.path.join(dir, file)
        if (os.path.isfile(path) or os.path.isdir(path)):
          os.chown(path, 0, 0)
